"""Summarize the TSV-like speech dataset generated by ``run.py``.

Usage:
    python3 analyze_dataset.py lp21/dataset-161225.csv

The script prints dataset-level statistics (row counts, date range, etc.) and
ranking-style highlights such as the most prolific speakers and the longest
speeches by word count.
"""

import argparse
import collections
import csv
from dataclasses import dataclass
from datetime import datetime
from typing import Iterable, List, Optional

DATE_FORMAT = "%d.%m.%Y"


@dataclass
class SpeechRow:
    session: str
    date: Optional[datetime]
    speech_id: str
    speaker: str
    text: str
    word_count: int


@dataclass
class DatasetStats:
    rows: List[SpeechRow]
    total_speeches: int
    unique_sessions: int
    unique_speakers: int
    date_min: Optional[datetime]
    date_max: Optional[datetime]
    empty_speakers: int
    empty_texts: int
    avg_word_count: float
    median_word_count: float
    speaker_counts: collections.Counter
    longest_speeches: List[SpeechRow]


def parse_rows(path: str) -> Iterable[SpeechRow]:
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.reader(handle, delimiter="\t")
        for raw in reader:
            if not raw:
                continue
            # Some lines may start with an empty field; drop blanks from the left.
            while raw and raw[0] == "":
                raw = raw[1:]
            if not raw:
                continue
            session = raw[0].strip()
            date_str = raw[1].strip() if len(raw) > 1 else ""
            speech_id = raw[2].strip() if len(raw) > 2 else ""
            speaker = raw[3].strip() if len(raw) > 3 else ""
            text = raw[4].strip() if len(raw) > 4 else ""
            word_count = len(text.split()) if text else 0
            try:
                date = datetime.strptime(date_str, DATE_FORMAT) if date_str else None
            except ValueError:
                date = None
            yield SpeechRow(
                session=session,
                date=date,
                speech_id=speech_id,
                speaker=speaker,
                text=text,
                word_count=word_count,
            )


def compute_stats(rows: Iterable[SpeechRow], top_n: int = 10) -> DatasetStats:
    row_list = list(rows)
    speaker_counts = collections.Counter()
    dates = []
    longest = []
    empty_speakers = 0
    empty_texts = 0

    for row in row_list:
        if not row.speaker or row.speaker == "-":
            empty_speakers += 1
        if not row.text:
            empty_texts += 1
        speaker_counts[row.speaker] += 1
        if row.date:
            dates.append(row.date)
        longest.append(row)

    longest.sort(key=lambda r: r.word_count, reverse=True)
    word_counts = [r.word_count for r in row_list]
    total_speeches = len(row_list)
    avg_word_count = sum(word_counts) / total_speeches if total_speeches else 0.0
    median_word_count = _median(word_counts)

    return DatasetStats(
        rows=row_list,
        total_speeches=total_speeches,
        unique_sessions=len({row.session for row in row_list}),
        unique_speakers=len(set(speaker_counts)),
        date_min=min(dates) if dates else None,
        date_max=max(dates) if dates else None,
        empty_speakers=empty_speakers,
        empty_texts=empty_texts,
        avg_word_count=avg_word_count,
        median_word_count=median_word_count,
        speaker_counts=speaker_counts,
        longest_speeches=longest[:top_n],
    )


def _median(values: List[int]) -> float:
    if not values:
        return 0.0
    values = sorted(values)
    mid = len(values) // 2
    if len(values) % 2:
        return float(values[mid])
    return (values[mid - 1] + values[mid]) / 2.0


def format_date(date: Optional[datetime]) -> str:
    return date.strftime(DATE_FORMAT) if date else "-"


def render_stats(stats: DatasetStats, top_n: int = 10) -> str:
    lines = [
        "Dataset overview:",
        f"  Total speeches:      {stats.total_speeches}",
        f"  Unique sessions:     {stats.unique_sessions}",
        f"  Unique speakers:     {stats.unique_speakers}",
        f"  Date range:          {format_date(stats.date_min)} — {format_date(stats.date_max)}",
        f"  Missing speakers:    {stats.empty_speakers}",
        f"  Empty texts:         {stats.empty_texts}",
        f"  Avg words per speech:{stats.avg_word_count:.1f}",
        f"  Median words:        {stats.median_word_count:.1f}",
        "",
        f"Top {top_n} speakers by speech count:",
    ]

    for speaker, count in stats.speaker_counts.most_common(top_n):
        lines.append(f"  {speaker or '-'} — {count}")

    lines.append("")
    lines.append(f"Top {top_n} speeches by length:")
    for row in stats.longest_speeches:
        snippet = (row.text[:140] + "…") if len(row.text) > 140 else row.text
        lines.append(
            f"  {row.speaker or '-'} (Session {row.session}, {format_date(row.date)}): {row.word_count} words — {snippet}"
        )

    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description="Summarize the generated Bundestag speech dataset")
    parser.add_argument("dataset", help="Path to the TSV-like dataset file (e.g., lp21/dataset-161225.csv)")
    parser.add_argument("--top", type=int, default=10, help="Number of top items to display")
    args = parser.parse_args()

    stats = compute_stats(parse_rows(args.dataset), top_n=args.top)
    print(render_stats(stats, top_n=args.top))


if __name__ == "__main__":
    main()
